#!/usr/bin/env python3
"""auto-generated-block.test.py — Unit test (Port; PROPOSAL_502_027)."""
import sys
import unittest
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent
sys.path.insert(0, str(SCRIPT_DIR.parent / "scripts" / "generators" / "lib"))
from auto_generated_block import (  # noqa
    has_block, extract_block_body, replace_block, check_drift, build_block_regex,
)


class TestAutoGeneratedBlock(unittest.TestCase):
    def test_has_block_present(self):
        content = (
            "# Title\n"
            "<!-- AUTO-GENERATED:BEGIN foo -->\n"
            "body\n"
            "<!-- AUTO-GENERATED:END foo -->\n"
            "tail"
        )
        self.assertTrue(has_block(content, "foo"))

    def test_has_block_missing(self):
        self.assertFalse(has_block("# no markers", "foo"))

    def test_extract_block_body(self):
        content = (
            "<!-- AUTO-GENERATED:BEGIN stats -->\n"
            "line1\n"
            "line2\n"
            "<!-- AUTO-GENERATED:END stats -->"
        )
        self.assertEqual(extract_block_body(content, "stats"), "line1\nline2")

    def test_extract_block_body_missing(self):
        self.assertIsNone(extract_block_body("nothing", "foo"))

    def test_replace_block_idempotent(self):
        content = (
            "before\n"
            "<!-- AUTO-GENERATED:BEGIN stats -->\n"
            "OLD\n"
            "<!-- AUTO-GENERATED:END stats -->\n"
            "after"
        )
        updated = replace_block(content, "stats", "NEW\nNEW2")
        self.assertEqual(extract_block_body(updated, "stats"), "NEW\nNEW2")
        again = replace_block(updated, "stats", "NEW\nNEW2")
        self.assertEqual(again, updated)

    def test_replace_block_throws(self):
        with self.assertRaisesRegex(ValueError, "block marker not found"):
            replace_block("no marker", "foo", "body")

    def test_check_drift_content_differs(self):
        content = (
            "<!-- AUTO-GENERATED:BEGIN s -->\n"
            "OLD\n"
            "<!-- AUTO-GENERATED:END s -->"
        )
        res = check_drift(content, "s", "NEW")
        self.assertTrue(res["drift"])
        self.assertEqual(res["reason"], "CONTENT_DIFFERS")

    def test_check_drift_missing_marker(self):
        res = check_drift("nothing", "s", "anything")
        self.assertTrue(res["drift"])
        self.assertEqual(res["reason"], "MISSING_MARKER")

    def test_check_drift_trim_tolerant(self):
        content = (
            "<!-- AUTO-GENERATED:BEGIN s -->\n"
            "\n"
            "BODY\n"
            "\n"
            "<!-- AUTO-GENERATED:END s -->"
        )
        res = check_drift(content, "s", "BODY")
        self.assertFalse(res["drift"])
        self.assertEqual(res["reason"], "IN_SYNC")

    def test_build_block_regex_escapes(self):
        regex = build_block_regex("stats.v1")
        text = "<!-- AUTO-GENERATED:BEGIN stats.v1 -->x<!-- AUTO-GENERATED:END stats.v1 -->"
        self.assertIsNotNone(regex.search(text))


if __name__ == "__main__":
    unittest.main(verbosity=2)
